ALTER TABLE public.player_access ADD COLUMN kicked_sessions text[] NOT NULL DEFAULT '{}';
CREATE OR REPLACE FUNCTION public.player_is_active() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT auth.uid() IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.player_access WHERE user_id = auth.uid() AND (banned OR coalesce(auth.jwt()->>'session_id','') = ANY(kicked_sessions))) $$;
CREATE OR REPLACE FUNCTION public.moderate_player(target uuid, action text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NOT public.player_is_active() OR NOT public.has_role(auth.uid(), 'admin') THEN RAISE EXCEPTION 'Admin access required'; END IF; IF action NOT IN ('kick','ban','unban') THEN RAISE EXCEPTION 'Invalid action'; END IF; IF public.has_role(target, 'admin') THEN RAISE EXCEPTION 'Admin accounts cannot be moderated'; END IF; IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = target) THEN RAISE EXCEPTION 'Player not found'; END IF; INSERT INTO public.player_access(user_id) VALUES (target) ON CONFLICT DO NOTHING; IF action = 'kick' THEN UPDATE public.player_access SET kicked_at = clock_timestamp(), kicked_sessions = kicked_sessions || coalesce((SELECT array_agg(id::text) FROM auth.sessions WHERE user_id = target), '{}'::text[]) WHERE user_id = target; ELSIF action = 'ban' THEN UPDATE public.player_access SET banned = true WHERE user_id = target; ELSE UPDATE public.player_access SET banned = false WHERE user_id = target; END IF; END $$;